const { load } = require('acme-config-loader');
const config = load('.env.test');

console.log('Configuration key names:');
const keys = Object.keys(config);
keys.forEach(key => {
    console.log(`- ${key}`);
});

console.log(`\nTotal number of keys: ${keys.length}`);

// Also show values (masked for security)
console.log('\nConfiguration values (masked):');
keys.forEach(key => {
    const value = config[key];
    const maskedValue = value.replace(/[^=:@-]/g, '*');
    console.log(`${key}=${maskedValue}`);
});

const { load } = require('acme-config-loader');

try {
    console.log('Test 1: Loading existing config');
    const config = load('.env.test');
    console.log('✓ Successfully loaded .env.test');

    console.log('\nTest 2: Trying to load non-existent config');
    try {
        load('.env.nonexistent');
        console.log('✗ Should have thrown error');
    } catch (error) {
        console.log('✓ Correctly threw error:', error.message);
    }

    console.log('\nTest 3: Testing empty file handling');
    const fs = require('fs');
    fs.writeFileSync('.env.empty', '');
    try {
        const emptyConfig = load('.env.empty');
        console.log('Empty config loaded with', Object.keys(emptyConfig).length, 'keys');
    } finally {
        fs.unlinkSync('.env.empty');
    }

} catch (error) {
    console.error('Error:', error);
    process.exit(1);
}

